/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { AgingStarScreen } from "../../src/aging-star/AgingStarScreen.js";
import { EnergyBalanceScreen } from "../../src/energy-balance/EnergyBalanceScreen.js";
import { EscapeScreen } from "../../src/escape/EscapeScreen.js";
import { GreenhouseScreen } from "../../src/greenhouse/GreenhouseScreen.js";
import HabitabilityLabColors from "../../src/HabitabilityLabColors.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { HabitabilityLabPreferencesModel } from "../../src/preferences/HabitabilityLabPreferencesModel.js";
import { ZoneEdgesScreen } from "../../src/zone-edges/ZoneEdgesScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  const simPreferences = new HabitabilityLabPreferencesModel(Tandem.ROOT.createTandem("preferences"));
  const screens = [
    new EnergyBalanceScreen({
      preferences: simPreferences,
      name: stringManager.getScreenNames().energyBalanceStringProperty,
      tandem: Tandem.ROOT.createTandem("energyBalanceScreen"),
      backgroundColorProperty: HabitabilityLabColors.backgroundColorProperty,
    }),
    new GreenhouseScreen({
      preferences: simPreferences,
      name: stringManager.getScreenNames().greenhouseStringProperty,
      tandem: Tandem.ROOT.createTandem("greenhouseScreen"),
      backgroundColorProperty: HabitabilityLabColors.backgroundColorProperty,
    }),
    new ZoneEdgesScreen({
      preferences: simPreferences,
      name: stringManager.getScreenNames().zoneEdgesStringProperty,
      tandem: Tandem.ROOT.createTandem("zoneEdgesScreen"),
      backgroundColorProperty: HabitabilityLabColors.backgroundColorProperty,
    }),
    new AgingStarScreen({
      name: stringManager.getScreenNames().agingStarStringProperty,
      tandem: Tandem.ROOT.createTandem("agingStarScreen"),
      backgroundColorProperty: HabitabilityLabColors.backgroundColorProperty,
    }),
    new EscapeScreen({
      preferences: simPreferences,
      name: stringManager.getScreenNames().escapeStringProperty,
      tandem: Tandem.ROOT.createTandem("escapeScreen"),
      backgroundColorProperty: HabitabilityLabColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { HabitabilityLabColors, stringManager } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
